const ROUTE_LABELS=new Map([['#/materials','素材库'],['#/today','今日待看'],['#/brief','每日选材晨报'],['#/accounts','对标账号'],['#/observations','观察记录']]);
const CONTENT_LABELS={product_showcase:'产品纯展示',product_selling:'产品带货',product_talking:'产品口播',creator_selling:'达人带货',ugc_review:'UGC 使用体验',comparison:'测评/对比',tutorial:'教程演示',story:'剧情植入',unboxing:'开箱素材',live_clip:'直播切片',brand_ad:'品牌广告',unknown:'暂不确定'};
const REVIEW_LABELS={pending:'待审核',approved:'已确认',rejected:'已淘汰',needs_review:'需复核'};
const STATE_LABELS={watching:'观察中',admitted:'已入素材库',unknown:'指标未知'};
const SCOPE_LABELS={product:'产品账号',category:'类目综合',reference:'框架参考',deferred:'暂不归类'};
export function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
export function qualityLabel(item){const size=item.width&&item.height?`${item.width}×${item.height}`:'尺寸未知';if(item.kind==='cover')return `封面 · ${size}`;if(item.kind==='clip')return `${item.duration_seconds||8} 秒短片 · ${size}`;const kind=item.kind==='hd'?'高清文件':item.kind==='full'?'完整文件':'轻量视频';return `${kind} · ${size}${item.duration_seconds?` · ${item.duration_seconds} 秒`:''}`;}
function mediaFrom(manifest,id){return manifest.media instanceof Map?manifest.media.get(id):manifest.media?.[id];}
function metric(value){return value===null||value===undefined?'未知':Number(value).toLocaleString('zh-CN');}
function nav(route){return [...ROUTE_LABELS].map(([href,label])=>`<a href="${href}"${href===route?' aria-current="page"':''}>${label}</a>`).join('');}
function badges(values=[],extra=''){return values.map(value=>`<span class="badge ${extra}">${escapeHtml(value)}</span>`).join('');}
function fieldValue(filters,name){return escapeHtml(filters?.[name]??'');}
function option(value,label,current){return `<option value="${escapeHtml(value)}"${current===value?' selected':''}>${escapeHtml(label)}</option>`;}
function selectField(label,name,records,key,current,{labels,arrays=false,all='全部'}={}){const values=new Set();for(const record of records){const raw=record[key];if(arrays){for(const value of raw||[])if(value)values.add(value);}else if(raw)values.add(raw);}const items=[...values].sort((a,b)=>String(a).localeCompare(String(b),'zh-CN'));return `<label>${label}<select name="${name}">${option('',all,current||'')}${items.map(value=>option(value,labels?.[value]||value,current||'')).join('')}</select></label>`;}
function textField(label,name,filters,type='text'){return `<label>${label}<input name="${name}" type="${type}" value="${fieldValue(filters,name)}"${type==='search'?' maxlength="100"':''}></label>`;}
function sortFields(filters,route){const routeSorts=route==='#/accounts'?[['followers','粉丝数'],['material_count','素材数'],['observation_count','观察数'],['account','账号名']]:route==='#/observations'?[['views','播放量'],['checked','最近检查'],['published','发布日期'],['account','账号名']]:route==='#/brief'?[['view_delta','播放增量'],['views','当前播放'],['published','发布日期']]:[['views','播放量'],['likes','点赞'],['comments','评论'],['shares','分享'],['published','发布日期'],['viral_score','爆款分']];return `<label>排序<select name="sort">${routeSorts.map(([value,label])=>option(value,label,filters.sort||'views')).join('')}</select></label><label>方向<select name="direction">${option('desc','从高到低',filters.direction||'desc')}${option('asc','从低到高',filters.direction||'desc')}</select></label>`;}
function filterForm(route,records,filters){let fields=textField('搜索账号或文案','query',filters,'search');if(route!=='#/accounts')fields+=selectField('账号','account',records,'account',filters.account);fields+=selectField('国家/地区','country',records,'country',filters.country);fields+=selectField('类目','category',records,'categories',filters.category,{arrays:true});fields+=selectField('产品','product',records,'products',filters.product,{arrays:true});
  if(route==='#/materials'||route==='#/today')fields+=`${selectField('审核状态','review_status',records,'review_status',filters.review_status,{labels:REVIEW_LABELS})}${selectField('内容类型','content_type',records,'content_type',filters.content_type,{labels:CONTENT_LABELS})}${selectField('视频','media',[{media:'available'},{media:'missing'}],'media',filters.media,{labels:{available:'已有视频',missing:'暂无视频'}})}${textField('开始日期','date_from',filters,'date')}${textField('结束日期','date_to',filters,'date')}`;
  if(route==='#/brief')fields+=`${selectField('晨报日期','report_day',records,'report_day',filters.report_day)}${selectField('增长信号','signal',records,'signal_quality',filters.signal)}${selectField('内容类型','content_type',records,'content_type',filters.content_type,{labels:CONTENT_LABELS})}${selectField('视频','media',[{media:'available'},{media:'missing'}],'media',filters.media,{labels:{available:'已有视频',missing:'暂无视频'}})}`;
  if(route==='#/accounts')fields+=selectField('归类范围','classification_scope',records,'classification_scope',filters.classification_scope,{labels:SCOPE_LABELS});
  if(route==='#/observations')fields+=`${selectField('记录状态','state',records,'state',filters.state,{labels:STATE_LABELS})}${textField('最低播放量','min_views',filters,'number')}${selectField('视频','media',[{media:'available'},{media:'missing'}],'media',filters.media,{labels:{available:'已有视频',missing:'暂无视频'}})}${textField('开始日期','date_from',filters,'date')}${textField('结束日期','date_to',filters,'date')}`;
  fields+=sortFields(filters,route);return `<form id="filters" class="filters">${fields}<button class="primary">筛选</button></form>`;
}
function paginationControls(pagination){if(!pagination||pagination.totalPages<=1)return '';return `<nav class="pagination" aria-label="分页"><button type="button" data-page="${pagination.page-1}"${pagination.page<=1?' disabled':''}>上一页</button><span>第 ${pagination.page}/${pagination.totalPages} 页</span><button type="button" data-page="${pagination.page+1}"${pagination.page>=pagination.totalPages?' disabled':''}>下一页</button></nav>`;}
function summaryCard(record){const m=record.metrics;return `<article class="summary-card"><p class="eyebrow">${escapeHtml(record.report_day)} · ${record.status==='complete'?'完整':'部分完成'}</p><h2>晨报数据概况</h2><div class="summary-metrics"><span>账号成功 <strong>${metric(m.accounts_success)}</strong></span><span>账号受阻 <strong>${metric(m.accounts_blocked)}</strong></span><span>增长信号 <strong>${metric(m.posts_sampled)}</strong></span><span>延后处理 <strong>${metric(m.posts_deferred)}</strong></span></div><p class="muted">发布时间 ${escapeHtml(record.published_at||'未知')}</p></article>`;}
function mediaBlock(record,manifest){const media=(record.media_ids||[]).map(id=>mediaFrom(manifest,id)).filter(Boolean);const cover=media.find(item=>item.kind==='cover');const playable=media.find(item=>item.kind!=='cover');if(!playable?.url)return `<div class="media-frame">${cover?.url?`<img src="${escapeHtml(cover.url)}" alt="作品封面" loading="lazy">`:'<span>本机没有可发布的封面</span>'}<span class="media-unavailable">本机视频待恢复</span></div>`;const label=qualityLabel(playable),poster=cover?.url||'';return `<button type="button" class="media-frame media-trigger" data-media-url="${escapeHtml(playable.url)}" data-media-poster="${escapeHtml(poster)}" data-media-label="${escapeHtml(label)}" aria-label="播放视频 ${escapeHtml(record.post_id||'')}">${poster?`<img src="${escapeHtml(poster)}" alt="作品封面" loading="lazy">`:'<span>点击加载视频</span>'}<span class="play-badge">▶ 播放视频</span></button>`;}
function sourceActions(record,playable){const source=record.source_url||record.profile_url||'';return `<div class="card-actions">${playable?`<button type="button" class="media-button" data-media-url="${escapeHtml(playable.url)}" data-media-poster="${escapeHtml(playable.poster||'')}" data-media-label="${escapeHtml(playable.label)}">播放视频</button>`:''}${source?`<a href="${escapeHtml(source)}" target="_blank" rel="noopener noreferrer">查看原作品</a><button type="button" data-copy-url="${escapeHtml(source)}">复制链接</button>`:''}</div>`;}
function accountCard(record){const title=record.display_name||record.account_display||record.username||'未命名账号';return `<article class="card account-card"><div class="card-body"><p class="eyebrow">${escapeHtml(SCOPE_LABELS[record.classification_scope]||record.classification_scope||'暂未归类')}</p><h2>${escapeHtml(title)}</h2><p class="account">@${escapeHtml(record.username||'')} · ${escapeHtml(record.country||'地区未知')}</p><div>${badges(record.categories)}${badges(record.products)}</div><div class="stats"><span>粉丝 <strong>${metric(record.metrics?.followers)}</strong></span><span>素材 <strong>${metric(record.metrics?.material_count)}</strong></span><span>观察 <strong>${metric(record.metrics?.observation_count)}</strong></span></div><p class="muted">状态 ${escapeHtml(record.account_status||'未知')} · 最近同步 ${escapeHtml(record.last_scanned_at?.slice(0,16)||'未知')}</p>${sourceActions(record,null)}</div></article>`;}
function contentCard(record,manifest){const media=(record.media_ids||[]).map(id=>mediaFrom(manifest,id)).filter(Boolean);const cover=media.find(item=>item.kind==='cover');const video=media.find(item=>item.kind!=='cover');const playable=video?.url?{url:video.url,poster:cover?.url||'',label:qualityLabel(video)}:null;const title=record.description||record.account_display||record.account||'未命名记录';const signals=[record.signal_quality,...(record.signal_tags||[])].filter(Boolean);return `<article class="card">${mediaBlock(record,manifest)}<div class="card-body"><p class="account">${escapeHtml(record.account_display||record.account||'')} · ${escapeHtml(record.country||'地区未知')}</p><h2>${escapeHtml(title)}</h2><div>${badges(record.categories)}${badges(record.products)}${badges(record.feature_tags,'feature')}${badges(signals,'signal')}</div>${record.content_type?`<p class="muted">${escapeHtml(CONTENT_LABELS[record.content_type]||record.content_type)}${record.review_status?` · ${escapeHtml(REVIEW_LABELS[record.review_status]||record.review_status)}`:''}${record.state?` · ${escapeHtml(STATE_LABELS[record.state]||record.state)}`:''}</p>`:''}${!playable&&record.media_reason?`<p class="media-note"><strong>本机视频待恢复：</strong>${escapeHtml(record.media_reason)}</p>`:''}<div class="stats"><span>播放 <strong>${metric(record.metrics?.views)}</strong></span><span>点赞 <strong>${metric(record.metrics?.likes)}</strong></span><span>评论 <strong>${metric(record.metrics?.comments)}</strong></span><span>分享 <strong>${metric(record.metrics?.shares)}</strong></span></div>${record.view_delta!==undefined?`<p class="growth">播放增量 <strong>${metric(record.view_delta)}</strong> · 当前 ${metric(record.current_views)}</p>`:''}<p class="muted">发布 ${escapeHtml(record.published_at?.slice(0,10)||'日期未知')}${record.checked_at?` · 检查 ${escapeHtml(record.checked_at.slice(0,16))}`:''}</p>${sourceActions(record,playable)}</div></article>`;}
function card(record,manifest,route){if(record.kind==='daily_summary')return summaryCard(record);if(route==='#/accounts')return accountCard(record);return contentCard(record,manifest);}
export function renderClosed(){return '<main class="closed"><div><span class="brand-mark">R</span><h1>网站暂时关闭</h1><p>请联系网站负责人确认恢复时间。</p></div></main>';}
export function renderPage({route,manifest,allRecords,records,totalRecords=records.length,pagination={page:1,totalPages:1},filters={},summaryRecord=null,closed=false}){if(closed)return renderClosed();const title=ROUTE_LABELS.get(route)||'素材库',pool=filters.pool||'company',source=allRecords||records;const counts={company:source.filter(r=>r.pool==='company').length,market:source.filter(r=>r.pool==='market').length,all:source.filter(r=>r.pool!=='all').length};return `<header class="topbar"><a class="brand" href="#/materials"><span class="brand-mark">R</span><span><strong>素材雷达</strong><small>员工只读站</small></span></a><nav aria-label="主要页面">${nav(route)}</nav></header><main class="page"><section class="notice"><strong>公开只读 · 员工版本</strong><p>已与本机工作台同步，可筛选、播放、下载和查看原作品；管理与审核操作仍由本机管理员完成。</p></section><section class="page-heading"><div><p class="eyebrow">CONTENT INTELLIGENCE</p><h1>${title}</h1><p class="muted">版本 ${escapeHtml(manifest.version)} · ${escapeHtml(manifest.generated_at)}</p></div><div class="pool-tabs"><button data-pool="company" aria-pressed="${pool==='company'}">公司对标 ${counts.company}</button><button data-pool="market" aria-pressed="${pool==='market'}">市场对标 ${counts.market}</button><button data-pool="all" aria-pressed="${pool==='all'}">全部 ${counts.all}</button></div></section>${filterForm(route,source,filters)}<p id="result-status" class="result-status">筛选结果 ${totalRecords} 条 · 已同步总数 ${counts.all} 条 · 第 ${pagination.page}/${pagination.totalPages} 页</p>${summaryRecord?summaryCard(summaryRecord):''}<section id="records" class="record-grid">${records.length?records.map(item=>card(item,manifest,route)).join(''):'<div class="empty">当前条件没有记录。</div>'}</section>${paginationControls(pagination)}</main><dialog id="media-dialog"><div class="dialog-head"><strong id="media-label">媒体预览</strong><button type="button" data-dialog-close aria-label="关闭预览">关闭</button></div><p id="media-status" class="media-status" role="status">准备播放</p><video controls playsinline preload="metadata"></video><div class="dialog-actions"><a class="open-media" target="_blank" rel="noopener noreferrer">在新窗口打开</a><a class="download" target="_blank" rel="noopener noreferrer">下载文件</a></div></dialog>`;}

